//! Diffcore web server — axum shell over `diffcore-core`.
//!
//! Health/SPA, projects API, graph + story-arc HTTP routes, and view builders are live.

pub mod analyze;
pub mod app;
pub mod graph_view;
pub mod projects;
pub mod story_arc;

pub use app::{app_router, AppState};
pub use projects::{
    AnalyzeRequest, OpenProjectRequest, ProjectError, ProjectRegistry, ProjectSummary,
};
pub use story_arc::{
    build_story_arc, EntireAdapter, ResidualAdapter, StoryArcEmptyReason, StoryArcEvent,
    StoryArcKind, StoryArcTimeline,
};
pub use graph_view::{
