//! Axum application router.

use std::sync::Arc;

use axum::extract::{Path, Query, State};
use axum::http::StatusCode;
use axum::response::{Html, IntoResponse, Response};
use axum::routing::{delete, get, post};
use axum::{Json, Router};
use serde::Deserialize;
use tokio::sync::Mutex;

use crate::graph_view::{
    build_graph_nodes, classify_graph_empty, GraphEmptyKind, GraphGranularity, GraphNodeView,
};
use crate::projects::{
    AnalyzeRequest, OpenProjectRequest, ProjectError, ProjectRegistry, ProjectSummary,
};
use crate::story_arc::{build_story_arc, EntireAdapter, ResidualAdapter, StoryArcTimeline};

/// Shared server state (multi-project session registry).
#[derive(Clone, Default)]
pub struct AppState {
    pub projects: Arc<Mutex<ProjectRegistry>>,
}

/// Build the HTTP router.
pub fn app_router(state: AppState) -> Router {
    Router::new()
        .route("/api/health", get(health))
        .route("/", get(spa_index))
        .route("/api/projects", post(open_project).get(list_projects))
        .route("/api/projects/:id", delete(delete_project))
        .route("/api/projects/:id/analyze", post(analyze_project))
        .route("/api/projects/:id/groups", get(project_groups))
        .route("/api/projects/:id/graph", get(project_graph))
        .route("/api/projects/:id/story-arc", get(project_story_arc))
        .with_state(state)
}

async fn health() -> Json<serde_json::Value> {
    Json(serde_json::json!({ "status": "ok" }))
}

async fn spa_index() -> Html<&'static str> {
    Html("<!DOCTYPE html><html><head><title>diffcore</title></head><body><div id=\"root\"></div></body></html>")
}

async fn open_project(
    State(state): State<AppState>,
    Json(req): Json<OpenProjectRequest>,
) -> Result<Json<ProjectSummary>, ProjectApiError> {
    let mut registry = state.projects.lock().await;
    let summary = registry.open(req)?;
    Ok(Json(summary))
}

async fn list_projects(State(state): State<AppState>) -> Json<Vec<ProjectSummary>> {
    let registry = state.projects.lock().await;
    Json(registry.list())
}

async fn delete_project(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<StatusCode, ProjectApiError> {
    let mut registry = state.projects.lock().await;
    registry.delete(&id)?;
    Ok(StatusCode::OK)
}

async fn analyze_project(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Json(req): Json<AnalyzeRequest>,
) -> Result<Json<serde_json::Value>, ProjectApiError> {
    let mut registry = state.projects.lock().await;
    let payload = registry.analyze(&id, req)?;
    Ok(Json(payload))
}

async fn project_groups(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<Json<serde_json::Value>, ProjectApiError> {
    let registry = state.projects.lock().await;
    let analysis = registry.last_analysis(&id)?;
    match analysis {
        Some(value) => {
            let groups = value
                .get("groups")
                .cloned()
                .unwrap_or_else(|| serde_json::json!([]));
            Ok(Json(serde_json::json!({ "groups": groups })))
        }
        None => Err(ProjectApiError(ProjectError::NotFound(
            "No analysis available. Run analyze first.".into(),
        ))),
    }
}

#[derive(Debug, Deserialize)]
struct GraphQuery {
    #[serde(default = "default_granularity")]
    granularity: GraphGranularity,
}

fn default_granularity() -> GraphGranularity {
    GraphGranularity::File
}

#[derive(Debug, serde::Serialize)]
struct GraphResponse {
    nodes: Vec<GraphNodeView>,
    #[serde(skip_serializing_if = "Option::is_none")]
    empty_kind: Option<GraphEmptyKind>,
}

async fn project_graph(
    State(state): State<AppState>,
    Path(id): Path<String>,
    Query(query): Query<GraphQuery>,
) -> Result<Json<GraphResponse>, ProjectApiError> {
    let registry = state.projects.lock().await;
    let edges_opt = registry.last_edges(&id)?;
    let analysis_ready = edges_opt.is_some();
    let edges = edges_opt.unwrap_or(&[]);
    let nodes = build_graph_nodes(edges, query.granularity);
    let empty_kind = if nodes.is_empty() {
        Some(classify_graph_empty(edges_opt, analysis_ready, false))
    } else {
        None
    };
    Ok(Json(GraphResponse { nodes, empty_kind }))
}

/// Default adapters: CLIs not wired yet → degrade with empty-reason codes.
struct MissingResidual;

#[async_trait::async_trait]
impl ResidualAdapter for MissingResidual {
    async fn list_force_events(
        &self,
    ) -> Result<Vec<crate::story_arc::StoryArcEvent>, String> {
        Err("residual: command not found".into())
    }
}

struct MissingEntire;

#[async_trait::async_trait]
impl EntireAdapter for MissingEntire {
    async fn list_checkpoint_events(
        &self,
    ) -> Result<Vec<crate::story_arc::StoryArcEvent>, String> {
        Err("entire: not enabled".into())
    }
}

async fn project_story_arc(
    State(state): State<AppState>,
    Path(id): Path<String>,
) -> Result<Json<StoryArcTimeline>, ProjectApiError> {
    {
        let registry = state.projects.lock().await;
        registry.get(&id)?;
    }
    let timeline = build_story_arc(&MissingResidual, &MissingEntire).await;
    Ok(Json(timeline))
}

struct ProjectApiError(ProjectError);

impl From<ProjectError> for ProjectApiError {
    fn from(err: ProjectError) -> Self {
        Self(err)
    }
}

impl IntoResponse for ProjectApiError {
    fn into_response(self) -> Response {
        let status = match &self.0 {
            ProjectError::NotFound(_) => StatusCode::NOT_FOUND,
            ProjectError::Unimplemented => StatusCode::NOT_IMPLEMENTED,
            ProjectError::Analyze(_) => StatusCode::INTERNAL_SERVER_ERROR,
        };
        (status, Json(serde_json::json!({ "error": self.0.to_string() }))).into_response()
    }
}
//! Multi-project session registry (in-memory).

use std::collections::HashMap;
use std::path::Path;

use serde::{Deserialize, Serialize};
use uuid::Uuid;

use crate::analyze::analyze_repo;
use diffcore_core::types::FlowEdge;

/// Request to open a review project session.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OpenProjectRequest {
    pub root_path: String,
    pub base: String,
    pub head: Option<String>,
}

/// Summary of an open project session.
#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
pub struct ProjectSummary {
    pub id: String,
    pub root_path: String,
    pub base: String,
    pub head: Option<String>,
}

/// Request body for analyze.
#[derive(Debug, Clone, Serialize, Deserialize, Default)]
pub struct AnalyzeRequest {
    #[serde(default)]
    pub force: bool,
}

#[derive(Debug, thiserror::Error, PartialEq, Eq)]
pub enum ProjectError {
    #[error("project not found: {0}")]
    NotFound(String),
    #[error("project registry operation not implemented")]
    Unimplemented,
    #[error("analyze failed: {0}")]
    Analyze(String),
}

#[derive(Debug, Clone)]
struct ProjectSession {
    summary: ProjectSummary,
    /// Last analyze JSON payload, if any.
    analysis: Option<serde_json::Value>,
    /// Edges derived from the last analysis (`None` = never analyzed).
    edges: Option<Vec<FlowEdge>>,
}

/// In-process multi-project registry.
#[derive(Debug, Default)]
pub struct ProjectRegistry {
    projects: HashMap<String, ProjectSession>,
}

impl ProjectRegistry {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn open(&mut self, req: OpenProjectRequest) -> Result<ProjectSummary, ProjectError> {
        let summary = ProjectSummary {
            id: Self::new_id(),
            root_path: req.root_path,
            base: req.base,
            head: req.head,
        };
        self.projects.insert(
            summary.id.clone(),
            ProjectSession {
                summary: summary.clone(),
                analysis: None,
                edges: None,
            },
        );
        Ok(summary)
    }

    pub fn list(&self) -> Vec<ProjectSummary> {
        self.projects
            .values()
            .map(|s| s.summary.clone())
            .collect()
    }

    pub fn delete(&mut self, id: &str) -> Result<(), ProjectError> {
        if self.projects.remove(id).is_none() {
            return Err(ProjectError::NotFound(id.to_string()));
        }
        Ok(())
    }

    pub fn get(&self, id: &str) -> Result<&ProjectSummary, ProjectError> {
        self.projects
            .get(id)
            .map(|s| &s.summary)
            .ok_or_else(|| ProjectError::NotFound(id.to_string()))
    }

    /// Last analysis JSON for a project, if analyze has run.
    pub fn last_analysis(&self, id: &str) -> Result<Option<&serde_json::Value>, ProjectError> {
        let session = self
            .projects
            .get(id)
            .ok_or_else(|| ProjectError::NotFound(id.to_string()))?;
        Ok(session.analysis.as_ref())
    }

    /// Last derived edges (`None` = never analyzed; `Some([])` = analyzed, empty).
    pub fn last_edges(&self, id: &str) -> Result<Option<&[FlowEdge]>, ProjectError> {
        let session = self
            .projects
            .get(id)
            .ok_or_else(|| ProjectError::NotFound(id.to_string()))?;
        Ok(session.edges.as_deref())
    }

    /// Store analysis JSON and extract edges from `groups[*].edges`.
    pub fn store_analysis(
        &mut self,
        id: &str,
        analysis: serde_json::Value,
    ) -> Result<(), ProjectError> {
        let session = self
            .projects
            .get_mut(id)
            .ok_or_else(|| ProjectError::NotFound(id.to_string()))?;
        let edges = extract_edges_from_analysis(&analysis);
        session.analysis = Some(analysis);
        session.edges = Some(edges);
        Ok(())
    }

    pub fn analyze(
        &mut self,
        id: &str,
        req: AnalyzeRequest,
    ) -> Result<serde_json::Value, ProjectError> {
        let summary = self
            .projects
            .get(id)
            .map(|s| s.summary.clone())
            .ok_or_else(|| ProjectError::NotFound(id.to_string()))?;

        let output = analyze_repo(
            Path::new(&summary.root_path),
            &summary.base,
            summary.head.as_deref(),
            req.force,
        )
        .map_err(ProjectError::Analyze)?;

        let payload = serde_json::to_value(&output)
            .map_err(|e| ProjectError::Analyze(format!("serialize analysis: {e}")))?;
        self.store_analysis(id, payload.clone())?;
        Ok(payload)
    }

    /// Allocate a project id.
    pub fn new_id() -> String {
        Uuid::new_v4().to_string()
    }
}

fn extract_edges_from_analysis(analysis: &serde_json::Value) -> Vec<FlowEdge> {
    let mut edges = Vec::new();
    let Some(groups) = analysis.get("groups").and_then(|g| g.as_array()) else {
        return edges;
    };
    for group in groups {
        let Some(group_edges) = group.get("edges") else {
            continue;
        };
        match serde_json::from_value::<Vec<FlowEdge>>(group_edges.clone()) {
            Ok(parsed) => edges.extend(parsed),
            Err(_) => continue,
        }
    }
    edges
}

  1 │ //! Real `diffcore-core` analyze pipeline for project sessions.
  2 │ //!
  3 │ //! Ports the Tauri/CLI base↔head path: git diff → parse → cluster → rank →
  4 │ //! `build_analysis_output`, with on-disk analysis cache (`force` skips load).
  5 │ 
  6 │ use std::collections::HashMap;
  7 │ use std::path::{Path, PathBuf};
  8 │ 
  9 │ use git2::Repository;
 10 │ 
 11 │ use diffcore_core::cache;
 12 │ use diffcore_core::cluster;
 13 │ use diffcore_core::config::DiffcoreConfig;
 14 │ use diffcore_core::entrypoint;
 15 │ use diffcore_core::flow::{self, FlowConfig};
 16 │ use diffcore_core::git;
 17 │ use diffcore_core::graph::SymbolGraph;
 18 │ use diffcore_core::output::{self, build_analysis_output};
 19 │ use diffcore_core::pipeline;
 20 │ use diffcore_core::rank;
 21 │ use diffcore_core::types::{AnalysisOutput, GroupRankInput};
 22 │ 
 23 │ /// Analyze `base`…`head` in `root` (head defaults to `"HEAD"`).
 24 │ ///
 25 │ /// When `force` is true, skip reading a cached `AnalysisOutput` (still writes cache).
 26 │ pub fn analyze_repo(
 27 │     root: &Path,
 28 │     base: &str,
 29 │     head: Option<&str>,
 30 │     force: bool,
 31 │ ) -> Result<AnalysisOutput, String> {
 32 │     let head_ref = head.unwrap_or("HEAD");
 33 │ 
 34 │     let repo_path = canonicalize_repo(root)?;
 35 │     let repo = Repository::discover(&repo_path)
 36 │         .map_err(|e| format!("Not a git repository: {e}"))?;
 37 │     let workdir = repo
 38 │         .workdir()
 39 │         .ok_or_else(|| "Bare repositories are not supported".to_string())?
 40 │         .to_path_buf();
 41 │ 
 42 │     let config = DiffcoreConfig::load_with_global_llm_from_dir(&workdir)
 43 │         .map_err(|e| format!("Config error: {e}"))?;
 44 │ 
 45 │     let diff_result = git::diff_refs(&repo, base, head_ref).map_err(|e| format!("Git diff: {e}"))?;
 46 │     let diff_source = output::diff_source_branch(
 47 │         base,
 48 │         head_ref,
 49 │         diff_result.base_sha.as_deref(),
 50 │         diff_result.head_sha.as_deref(),
 51 │     );
 52 │ 
 53 │     if diff_result.files.is_empty() {
 54 │         return Ok(AnalysisOutput {
 55 │             version: "1.0.0".to_string(),
 56 │             diff_source,
 57 │             summary: diffcore_core::types::AnalysisSummary {
 58 │                 total_files_changed: 0,
 59 │                 total_groups: 0,
 60 │                 languages_detected: vec![],
 61 │                 frameworks_detected: vec![],
 62 │             },
 63 │             groups: vec![],
 64 │             infrastructure_group: None,
 65 │             annotations: None,
 66 │         });
 67 │     }
 68 │ 
 69 │     let cache_key = cache::compute_cache_key(&diff_result);
 70 │     if !force {
 71 │         if let Some(cached) = cache::load_cached(&workdir, &cache_key) {
 72 │             return Ok(cached);
 73 │         }
 74 │     }
 75 │ 
 76 │     let file_inputs: Vec<(&str, &str)> = diff_result
 77 │         .files
 78 │         .iter()
 79 │         .filter_map(|file_diff| {
 80 │             let content = file_diff
 81 │                 .new_content
 82 │                 .as_deref()
 83 │                 .or(file_diff.old_content.as_deref())?;
 84 │             let path = file_diff.path();
 85 │             if config.is_ignored(path) {
 86 │                 return None;
 87 │             }
 88 │             Some((path, content))
 89 │         })
 90 │         .collect();
 91 │ 
 92 │     let parsed_files = pipeline::parse_files_parallel(&file_inputs);
 93 │     let workspace_map = diffcore_core::graph::build_workspace_map(&workdir);
 94 │     let mut graph = SymbolGraph::build_with_workspace(&parsed_files, &workspace_map);
 95 │     let entrypoints = entrypoint::detect_entrypoints(&parsed_files);
 96 │     let flow_analysis = flow::analyze_data_flow(&parsed_files, &FlowConfig::default());
 97 │     flow::enrich_graph(&mut graph, &flow_analysis);
 98 │ 
 99 │     let changed_files: Vec<String> = diff_result
100 │         .files
101 │         .iter()
102 │         .filter(|f| !config.is_ignored(f.path()))
103 │         .map(|f| f.path().to_string())
104 │         .collect();
105 │     let diff_stats: HashMap<&str, (u32, u32, u32)> = diff_result
106 │         .files
107 │         .iter()
108 │         .map(|f| (f.path(), (f.additions, f.deletions, f.hunks.len() as u32)))
109 │         .collect();
110 │ 
111 │     let mut cluster_result = cluster::cluster_files(&graph, &entrypoints, &changed_files);
112 │     for group in cluster_result.groups.iter_mut() {
113 │         for fc in group.files.iter_mut() {
114 │             if let Some(&(additions, deletions, hunks)) = diff_stats.get(fc.path.as_str()) {
115 │                 fc.changes.additions = additions;
116 │                 fc.changes.deletions = deletions;
117 │                 fc.changes.hunks = hunks;
118 │             }
119 │         }
120 │     }
121 │ 
122 │     let weights = config.ranking.clone();
123 │     let rank_inputs: Vec<GroupRankInput> = cluster_result
124 │         .groups
125 │         .iter()
126 │         .map(|group| {
127 │             let risk_flags = output::compute_group_risk_flags(
128 │                 &group
129 │                     .files
130 │                     .iter()
131 │                     .map(|f| f.path.as_str())
132 │                     .collect::<Vec<_>>(),
133 │             );
134 │             let total_add: u32 = group.files.iter().map(|f| f.changes.additions).sum();
135 │             let total_del: u32 = group.files.iter().map(|f| f.changes.deletions).sum();
136 │ 
137 │             GroupRankInput {
138 │                 group_id: group.id.clone(),
139 │                 risk: rank::compute_risk_score(
140 │                     risk_flags.has_schema_change,
141 │                     risk_flags.has_api_change,
142 │                     risk_flags.has_auth_change,
143 │                     false,
144 │                 ),
145 │                 centrality: 0.5,
146 │                 surface_area: rank::compute_surface_area(total_add, total_del, 1000),
147 │                 uncertainty: if risk_flags.has_test_only { 0.1 } else { 0.5 },
148 │             }
149 │         })
150 │         .collect();
151 │ 
152 │     let ranked = rank::rank_groups(&rank_inputs, &weights);
153 │     let analysis_output = build_analysis_output(
154 │         &diff_result,
155 │         diff_source,
156 │         &parsed_files,
157 │         &cluster_result,
158 │         &ranked,
159 │     );
160 │ 
161 │     cache::store_cached(&workdir, &cache_key, &analysis_output);
162 │     Ok(analysis_output)
163 │ }
