 3 │ use serde::{Deserialize, Serialize};
 4 │ 
 5 │ use diffcore_core::types::FlowEdge;
 6 │ 
 7 │ /// Requested graph granularity for the web UI / API.
 8 │ #[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
 9 │ #[serde(rename_all = "snake_case")]
10 │ pub enum GraphGranularity {
11 │     File,
12 │     Symbol,
13 │ }
14 │ 
15 │ /// A node rendered in the interactive graph.
16 │ #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
17 │ pub struct GraphNodeView {
18 │     pub id: String,
19 │     pub label: String,
20 │     pub file: String,
21 │ }
22 │ 
23 │ /// Why the graph pane is empty.
24 │ #[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
25 │ #[serde(rename_all = "snake_case")]
26 │ pub enum GraphEmptyKind {
27 │     Loading,
28 │     NoEdgesInGroup,
29 │     AnalysisMissingEdges,
30 │ }
31 │ 
32 │ fn file_of(endpoint: &str) -> String {
33 │     endpoint.split("::").next().unwrap_or(endpoint).to_string()
34 │ }
35 │ 
36 │ fn push_unique(nodes: &mut Vec<GraphNodeView>, id: String, label: String, file: String) {
37 │     if !nodes.iter().any(|n| n.id == id) {
38 │         nodes.push(GraphNodeView { id, label, file });
39 │     }
40 │ }
41 │ 
42 │ /// Build the node set for a list of flow edges at the requested granularity.
43 │ pub fn build_graph_nodes(edges: &[FlowEdge], granularity: GraphGranularity) -> Vec<GraphNodeView> {
44 │     let mut nodes: Vec<GraphNodeView> = Vec::new();
45 │     for edge in edges {
46 │         for endpoint in [&edge.from, &edge.to] {
47 │             let file = file_of(endpoint);
48 │             match granularity {
49 │                 GraphGranularity::File => {
50 │                     push_unique(&mut nodes, file.clone(), file.clone(), file);
51 │                 }
52 │                 GraphGranularity::Symbol => {
53 │                     let id = endpoint.clone();
54 │                     let label = endpoint
55 │                         .rsplit("::")
56 │                         .next()
57 │                         .unwrap_or(endpoint)
58 │                         .to_string();
59 │                     push_unique(&mut nodes, id, label, file);
60 │                 }
61 │             }
62 │         }
63 │     }
64 │     nodes
65 │ }
66 │ 
67 │ /// Classify an empty graph pane.
68 │ pub fn classify_graph_empty(
69 │     edges: Option<&[FlowEdge]>,
70 │     analysis_ready: bool,
71 │     is_loading: bool,
72 │ ) -> GraphEmptyKind {
73 │     if is_loading {
74 │         return GraphEmptyKind::Loading;
75 │     }
76 │     if edges.is_none() || !analysis_ready {
77 │         return GraphEmptyKind::AnalysisMissingEdges;
78 │     }
79 │     GraphEmptyKind::NoEdgesInGroup
80 │ }
