53 │ /// Build a typed story-arc timeline from residual + Entire adapters.
54 │ ///
55 │ /// Adapter errors (CLI missing / not enabled) degrade to empty events plus
56 │ /// `ResidualNotInitialized` / `EntireNotEnabled` rather than failing the timeline.
57 │ pub async fn build_story_arc(
58 │     residual: &dyn ResidualAdapter,
59 │     entire: &dyn EntireAdapter,
60 │ ) -> StoryArcTimeline {
61 │     let mut events = Vec::new();
62 │     let mut empty_reasons = Vec::new();
63 │ 
64 │     match residual.list_force_events().await {
65 │         Ok(mut residual_events) => events.append(&mut residual_events),
66 │         Err(_) => empty_reasons.push(StoryArcEmptyReason::ResidualNotInitialized),
67 │     }
68 │ 
69 │     match entire.list_checkpoint_events().await {
70 │         Ok(mut entire_events) => events.append(&mut entire_events),
71 │         Err(_) => empty_reasons.push(StoryArcEmptyReason::EntireNotEnabled),
