//! Red contract: server boots routes for health + SPA index.

use axum::body::Body;
use axum::http::{Request, StatusCode};
use http_body_util::BodyExt;
use tower::ServiceExt;

use diffcore_server::{app_router, AppState};

async fn get(path: &str) -> (StatusCode, String) {
    let app = app_router(AppState::default());
    let response = app
        .oneshot(
            Request::builder()
                .uri(path)
                .body(Body::empty())
                .expect("request"),
        )
        .await
        .expect("response");
    let status = response.status();
    let bytes = response
        .into_body()
        .collect()
        .await
        .expect("body")
        .to_bytes();
    let body = String::from_utf8_lossy(&bytes).into_owned();
    (status, body)
}

#[tokio::test]
async fn get_api_health_returns_ok() {
    let (status, body) = get("/api/health").await;
    assert_eq!(
        status,
        StatusCode::OK,
        "GET /api/health must return 200 once the server skeleton lands; body={body:?}"
    );
    let json: serde_json::Value =
        serde_json::from_str(&body).expect("health body should be JSON");
    assert_eq!(json.get("status").and_then(|v| v.as_str()), Some("ok"));
}

#[tokio::test]
async fn get_root_serves_spa_index_or_placeholder() {
    let (status, body) = get("/").await;
    assert_eq!(
        status,
        StatusCode::OK,
        "GET / must serve the SPA index (or placeholder HTML)"
    );
    let lower = body.to_ascii_lowercase();
    assert!(
        lower.contains("<html") || lower.contains("<!doctype html"),
        "expected HTML document, got: {body:?}"
    );
}
//! Guard: Tauri must stay out of the workspace after the web-server migration.

use std::fs;
use std::path::PathBuf;

fn workspace_cargo_toml() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .join("Cargo.toml")
}

#[test]
fn workspace_members_exclude_diffcore_tauri() {
    let manifest = fs::read_to_string(workspace_cargo_toml()).expect("read workspace Cargo.toml");

    // Grab only the `members = [ ... ]` array from the root `[workspace]` table.
    let members_start = manifest
        .find("members")
        .expect("workspace members key");
    let after_members = &manifest[members_start..];
    let array_start = after_members
        .find('[')
        .expect("members array open");
    let array_body = &after_members[array_start + 1..];
    let array_end = array_body
        .find(']')
        .expect("members array close");
    let members = &array_body[..array_end];

    assert!(
        !members.contains("diffcore-tauri"),
        "workspace members must not include crates/diffcore-tauri after Tauri removal"
    );
    assert!(
        members.contains("diffcore-server"),
        "workspace members must include crates/diffcore-server"
    );
    assert!(
        !PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../diffcore-tauri")
            .exists(),
        "crates/diffcore-tauri directory must be deleted"
    );
}
