import type { AnalysisOutput, FlowGroup } from "../types";

export const API = {
  health: "/api/health",
  projects: "/api/projects",
  analyze: (id: string) => `/api/projects/${id}/analyze`,
  groups: (id: string) => `/api/projects/${id}/groups`,
  storyArc: (id: string) => `/api/projects/${id}/story-arc`,
  graph: (id: string, granularity: "file" | "symbol") =>
    `/api/projects/${id}/graph?granularity=${granularity}`,
} as const;

export type HealthResponse = { status: "ok" };

export type GraphGranularity = "file" | "symbol";

export type GraphEmptyKind = "loading" | "no_edges_in_group" | "analysis_missing_edges";

export type GraphNodeView = {
  id: string;
  label: string;
  file: string;
};

export type GraphResponse = {
  nodes: GraphNodeView[];
  empty_kind?: GraphEmptyKind;
};

export type StoryArcKind =
  | "residual_force"
  | "entire_checkpoint"
  | "entire_dispatch"
  | "git_commit";

export type StoryArcEmptyReason =
  | "residual_not_initialized"
  | "entire_not_enabled"
  | "no_events";

export type StoryArcEvent = {
  kind: StoryArcKind;
  at: string;
  title: string;
  body: string;
  refs?: string[];
};

export type StoryArcTimeline = {
  events: StoryArcEvent[];
  empty_reasons: StoryArcEmptyReason[];
};

export type AnalyzeRequestBody = {
  force?: boolean;
};

async function parseJson<T>(res: Response): Promise<T> {
  if (!res.ok) {
    const text = await res.text().catch(() => "");
    throw new Error(`HTTP ${res.status}${text ? `: ${text}` : ""}`);
  }
  return (await res.json()) as T;
}

export async function getHealth(): Promise<HealthResponse> {
  const res = await fetch(API.health);
  return parseJson<HealthResponse>(res);
}

export async function openProject(body: {
  root_path: string;
  base: string;
  head?: string | null;
}): Promise<{ id: string }> {
  const res = await fetch(API.projects, {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify(body),
  });
  return parseJson<{ id: string }>(res);
}

export async function listProjects(): Promise<Array<{ id: string }>> {
  const res = await fetch(API.projects);
  return parseJson<Array<{ id: string }>>(res);
}

export async function deleteProject(id: string): Promise<void> {
  const res = await fetch(`${API.projects}/${id}`, { method: "DELETE" });
  if (!res.ok) {
    const text = await res.text().catch(() => "");
    throw new Error(`HTTP ${res.status}${text ? `: ${text}` : ""}`);
  }
}

/** POST /api/projects/:id/analyze — runs diffcore-core pipeline. */
export async function analyzeProject(
  id: string,
  body: AnalyzeRequestBody = {},
): Promise<AnalysisOutput | { groups: FlowGroup[] }> {
  const res = await fetch(API.analyze(id), {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({ force: body.force ?? false }),
  });
  return parseJson(res);
}

/** GET /api/projects/:id/groups — from last analysis; 404 if not analyzed yet. */
export async function listGroups(id: string): Promise<FlowGroup[]> {
  const res = await fetch(API.groups(id));
  if (res.status === 404) {
    const analysis = await analyzeProject(id);
    return (analysis as { groups?: FlowGroup[] }).groups ?? [];
  }
  const data = await parseJson<{ groups: FlowGroup[] } | FlowGroup[]>(res);
  return Array.isArray(data) ? data : (data.groups ?? []);
}

/** GET /api/projects/:id/graph?granularity= */
export async function getGraph(
  id: string,
  granularity: GraphGranularity = "file",
): Promise<GraphResponse> {
  const res = await fetch(API.graph(id, granularity));
  return parseJson<GraphResponse>(res);
}

/** GET /api/projects/:id/story-arc */
export async function getStoryArc(id: string): Promise<StoryArcTimeline> {
  const res = await fetch(API.storyArc(id));
  return parseJson<StoryArcTimeline>(res);
}
/**
 * Multi-project tab store — open/switch/close with isolated tab state.
 */

export interface ProjectTab {
  id: string;
  rootPath: string;
  base: string;
  head: string | null;
  /** Server-side project id from POST /api/projects, when available. */
  serverId?: string;
}

export interface ProjectTabStore {
  tabs: ProjectTab[];
  activeId: string | null;
  open(tab: Omit<ProjectTab, "id"> & { id?: string }): ProjectTab;
  close(id: string): void;
  switchTo(id: string): void;
}

let nextId = 0;

export function createProjectTabStore(): ProjectTabStore {
  const store: ProjectTabStore = {
    tabs: [],
    activeId: null,
    open(tab) {
      const id = tab.id ?? `project-${++nextId}`;
      const projectTab: ProjectTab = {
        id,
        rootPath: tab.rootPath,
        base: tab.base,
        head: tab.head,
        serverId: tab.serverId,
      };
      store.tabs = [...store.tabs, projectTab];
      store.activeId = id;
      return projectTab;
    },
    close(id) {
      const remaining = store.tabs.filter((t) => t.id !== id);
      store.tabs = remaining;
      if (store.activeId === id) {
        store.activeId = remaining[remaining.length - 1]?.id ?? null;
      }
    },
    switchTo(id) {
      if (store.tabs.some((t) => t.id === id)) {
        store.activeId = id;
      }
    },
  };
  return store;
}
