  files: string[];
  entities: Array<{ id: string; file: string; startLine: number; endLine: number }>;
}

export interface EntityHunkView {
  entityId: string;
  file: string;
  startLine: number;
  endLine: number;
}

export interface TierController {
  currentTier: DiffTier;
  selectedGroupId: string | null;
  selectedEntityId: string | null;
  entityHunk: EntityHunkView | null;
  selectGroup(groupId: string): void;
  selectEntity(entityId: string): void;
  deepenToFile(): void;
  deepenToGroupStream(): void;
  resetToManifest(): void;
}

export function createTierController(fixture: GroupFixture): TierController {
  const controller: TierController = {
    currentTier: "T0",
    selectedGroupId: null,
    selectedEntityId: null,
    entityHunk: null,
    selectGroup(groupId: string) {
      controller.currentTier = "T1";
      controller.selectedGroupId = groupId;
    },
    selectEntity(entityId: string) {
      const entity = fixture.entities.find((e) => e.id === entityId);
      if (!entity) {
        return;
      }
      controller.currentTier = "T2";
      controller.selectedEntityId = entityId;
      controller.entityHunk = {
        entityId: entity.id,
        file: entity.file,
        startLine: entity.startLine,
        endLine: entity.endLine,
      };
    },
    deepenToFile() {
      controller.currentTier = "T3";
    },
    deepenToGroupStream() {
      controller.currentTier = "T4";
    },
    resetToManifest() {
      controller.currentTier = "T1";
    },
  };
  return controller;
}

