type ShellAction =
  | { type: "open"; rootPath: string; base: string; head: string | null; serverId?: string }
  | { type: "switch"; id: string }
  | { type: "close"; id: string };

function shellReducer(state: ShellState, action: ShellAction): ShellState {
  switch (action.type) {
    case "open":
      state.store.open({
        rootPath: action.rootPath,
        base: action.base,
        head: action.head,
        serverId: action.serverId,
      });
      break;
    case "switch":
      state.store.switchTo(action.id);
      break;
    case "close":
      state.store.close(action.id);
      break;
  }
  return { store: state.store, revision: state.revision + 1 };
}

type TierAction =
  | { type: "selectGroup"; groupId: string }
  | { type: "selectEntity"; entityId: string }
  | { type: "deepenToFile" }
  | { type: "deepenToGroupStream" }
  | { type: "resetToManifest" };

function tierReducer(
  state: { controller: TierController; revision: number },
  action: TierAction,
): { controller: TierController; revision: number } {
  switch (action.type) {
    case "selectGroup":
      state.controller.selectGroup(action.groupId);
      break;
    case "selectEntity":
      state.controller.selectEntity(action.entityId);
      break;
    case "deepenToFile":
      state.controller.deepenToFile();
      break;
    case "deepenToGroupStream":
      state.controller.deepenToGroupStream();
      break;
    case "resetToManifest":
      state.controller.resetToManifest();
      break;
  }
  return { controller: state.controller, revision: state.revision + 1 };
}

function tabLabel(tab: ProjectTab): string {
  const head = tab.head ?? "HEAD";
  const leaf = tab.rootPath.split(/[/\\]/).filter(Boolean).at(-1) ?? tab.rootPath;
  return `${leaf} (${tab.base}…${head})`;
}

function formatTierDebug(controller: TierController): string {
  const lines = [
    `tier: ${controller.currentTier}`,
    `group: ${controller.selectedGroupId ?? "(none)"}`,
    `entity: ${controller.selectedEntityId ?? "(none)"}`,
  ];
  if (controller.entityHunk) {
    const h = controller.entityHunk;
    lines.push(`hunk: ${h.file}:${h.startLine}-${h.endLine}`);
  }
  return lines.join("\n");
}

