function sliceLines(text: string, startLine: number, endLine: number): string {
  const lines = text.split("\n");
  const start = Math.max(0, startLine - 1);
  const end = Math.min(lines.length, Math.max(start, endLine));
  return lines.slice(start, end).join("\n") + (end > start ? "\n" : "");
}

function filePair(
  path: string,
  contents: Record<string, FixtureFileContents>,
  range?: { startLine: number; endLine: number },
) {
  const pair = contents[path] ?? { before: "", after: "" };
  const before = range
    ? sliceLines(pair.before, range.startLine, range.endLine)
    : pair.before;
  const after = range
    ? sliceLines(pair.after, range.startLine, range.endLine)
    : pair.after;
  return {
    oldFile: { name: path, contents: before },
    newFile: { name: path, contents: after },
  };
}

